const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '比例尺 1:25000' },
      { kind: 'text', payload: '图上两地距离 6 厘米' },
      { kind: 'text', payload: '实际距离 150000 厘米' },
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: '6' }
    ];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var x0 = Math.max(56, w * 0.14);
    var x1 = Math.min(w - 56, w * 0.86);
    if (x1 <= x0) {
      x0 = 40;
      x1 = w - 40;
    }
    var y = h * 0.52;
    var tick = Math.max(10, Math.min(20, h * 0.09));
    var cmds = [];
    cmds = cmds.concat(visualSdk.polyline([[x0, y], [x1, y]]));
    var i;
    for (i = 0; i <= 6; i++) {
      var x = x0 + (x1 - x0) * i / 6;
      cmds = cmds.concat(visualSdk.polyline([[x, y - tick / 2], [x, y + tick / 2]]));
    }
    var labels = [
      { type: 'label', x: w / 2, y: h * 0.20, text: '比例尺 1:25000', fontSize: 16, textAnchor: 'middle', fill: '#26354a' },
      { type: 'label', x: w / 2, y: h * 0.40, text: '图上两地距离 6 厘米', fontSize: 15, textAnchor: 'middle', fill: '#26354a' },
      { type: 'label', x: w / 2, y: y + tick + 34, text: '实际距离 150000 厘米', fontSize: 16, textAnchor: 'middle', fill: '#26354a' },
      { type: 'label', x: x0, y: y + tick + 10, text: '0', fontSize: 13, textAnchor: 'middle', fill: '#26354a' },
      { type: 'label', x: x1, y: y + tick + 10, text: '6', fontSize: 13, textAnchor: 'middle', fill: '#26354a' }
    ];
    var children = [
      { type: 'path', pathId: 'scaleLine', stroke: '#26354a', strokeWidth: 2, fill: 'none' }
    ].concat(labels);
    return {
      schemaVersion: 1,
      sceneId: 'scale-distance',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [{ id: 'scaleLine', commands: cmds }],
      root: { type: 'group', children: children }
    };
  }
};
